import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Mining","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/professions/mining.md","filePath":"game-design/professions/mining.md"}'),r={name:"game-design/professions/mining.md"};function t(s,e,l,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="mining" tabindex="-1">Mining <a class="header-anchor" href="#mining" aria-label="Permalink to &quot;Mining&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/professions/mining.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Mining should be geology + extraction + world modification, not only &quot;click mountain -&gt; ore&quot;.</p><h3 id="world-changes" tabindex="-1">World changes <a class="header-anchor" href="#world-changes" aria-label="Permalink to &quot;World changes&quot;">​</a></h3><ul><li>mineral rock tiles physically deplete;</li><li>repeated extraction can break a rock/tile down until it becomes traversable;</li><li>mining can physically alter navigation.</li></ul><p>Regional geology should preserve the identity of mining regions without naïve exact-tile respawn. Possible regeneration/resealing model:</p><ul><li>abandoned excavation;</li><li>instability;</li><li>partial cave-in;</li><li>rubble;</li><li>mineral-bearing rock returns/reappears regionally.</li></ul><p>Do not commit to exact timing or algorithm here unless already documented elsewhere.</p><h3 id="prospecting-and-extraction" tabindex="-1">Prospecting and extraction <a class="header-anchor" href="#prospecting-and-extraction" aria-label="Permalink to &quot;Prospecting and extraction&quot;">​</a></h3><ul><li>prospecting;</li><li>rock/ore recognition;</li><li>structural awareness;</li><li>reading terrain clues;</li><li>extracting higher yield/quality through better decisions.</li></ul><h3 id="geological-journal" tabindex="-1">Geological Journal <a class="header-anchor" href="#geological-journal" aria-label="Permalink to &quot;Geological Journal&quot;">​</a></h3><ul><li>rock types;</li><li>ores;</li><li>vein characteristics;</li><li>regions;</li><li>observations.</li></ul><h3 id="material-variation" tabindex="-1">Material variation <a class="header-anchor" href="#material-variation" aria-label="Permalink to &quot;Material variation&quot;">​</a></h3><ul><li>regional composition;</li><li>provenance;</li><li>impurity profile;</li><li>local seed/quality.</li></ul><p>Keep abstraction manageable.</p><p>Mining knowledge should tell the player what is present and how promising it is. Blacksmithing knowledge should tell them what that material is useful for.</p><p>Mining can include stability/cave-in concerns at advanced levels, potentially connecting to Carpentry supports and Tinkering mechanisms.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Geological Journal.</strong> Record rock types, ores, veins, regions and observations. Prospecting and structural expertise provide paths beyond raw extraction.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Mining identifies what is present and how promising it is; Blacksmithing identifies what the material is useful for. Carpentry supports and Tinkering mechanisms are potential advanced mine-stability partners.</p><p><a href="/Syrolands-Public/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/game-design/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/game-design/living-world.html#terrain-and-authored-geology">Authored geology</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Which authored rocks are mutable; regional resealing and recovery; excavation permissions and trapped-player safety; collapse/support rules; yield, provenance and impurity disclosure. No exact timer, regeneration algorithm or unrestricted terrain digging is selected.</p><p>The <a href="/Syrolands-Public/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p>',31)])])}const u=a(r,[["render",t]]);export{g as __pageData,u as default};
